int64_t dm_fib(int64_t n) {
    if ((n <= 1)) {
        return n;
    }
    return (dm_fib((n - 1)) + dm_fib((n - 2)));
}

void dm_worker35(void) {
    int64_t r = dm_fib(35);
    dm_file_write(dm_string_from_cstr("/tmp/pfib_35.txt"), dm_int_to_string(r));
}

void dm_worker36(void) {
    int64_t r = dm_fib(36);
    dm_file_write(dm_string_from_cstr("/tmp/pfib_36.txt"), dm_int_to_string(r));
}

void dm_worker37(void) {
    int64_t r = dm_fib(37);
    dm_file_write(dm_string_from_cstr("/tmp/pfib_37.txt"), dm_int_to_string(r));
}

void dm_worker38(void) {
    int64_t r = dm_fib(38);
    dm_file_write(dm_string_from_cstr("/tmp/pfib_38.txt"), dm_int_to_string(r));
}

void dm_main(void) {
    int64_t t1 = dm_thread_spawn(dm_worker35);
    int64_t t2 = dm_thread_spawn(dm_worker36);
    int64_t t3 = dm_thread_spawn(dm_worker37);
    int64_t t4 = dm_thread_spawn(dm_worker38);
    dm_thread_join_id(t1);
    dm_thread_join_id(t2);
    dm_thread_join_id(t3);
    dm_thread_join_id(t4);
    int64_t r1 = dm_parse_int(dm_file_read(dm_string_from_cstr("/tmp/pfib_35.txt")));
    int64_t r2 = dm_parse_int(dm_file_read(dm_string_from_cstr("/tmp/pfib_36.txt")));
    int64_t r3 = dm_parse_int(dm_file_read(dm_string_from_cstr("/tmp/pfib_37.txt")));
    int64_t r4 = dm_parse_int(dm_file_read(dm_string_from_cstr("/tmp/pfib_38.txt")));
    dm_println_str(dm_int_to_string((((r1 + r2) + r3) + r4)));
}


int main(int argc, char** argv) {
    dm_argc = argc;
    dm_argv = argv;
    dm_main();
    return 0;
}
